if doc.custom_company_level == "Global":
    existing_global = frappe.db.get_value("Company", 
        {"custom_company_level": "Global", "name": ["!=", doc.name]}, 
        "name"
    )
    if existing_global:
        frappe.throw(
            title="Validation Error",
            msg=f"You cannot mark <b>{doc.name}</b> as Global.<br><br>The company <b>{existing_global}</b> is already set as Global.<br>Only one Global company is allowed."
        )

child_table = doc.get("custom_organization_ids")

if child_table:
    for row in child_table:
        
        if row.organization and not row.org_employee_id:
            
            company_abbr = frappe.db.get_value("Company", row.organization, "abbr")
            
            if company_abbr:
                prefix = company_abbr.strip().upper() + "-"
                
                existing_ids = frappe.get_all(
                    "Employee Sub ID",
                    filters={"org_employee_id": ("like", f"{prefix}%")},
                    fields=["org_employee_id"]
                )
                
                if existing_ids:
                    numbers = []
                    for item in existing_ids:
                        if item.org_employee_id:
                            try:
                                num = int(item.org_employee_id.split("-")[-1])
                                numbers.append(num)
                            except:
                                pass
                    next_num = max(numbers) + 1 if numbers else 1
                else:
                    next_num = 1
                    
                row.org_employee_id = f"{prefix}{str(next_num).zfill(3)}"

child_table = doc.get("custom_organization_ids")

if child_table:
    for row in child_table:
        # Only generate if the row has a company selected and the ID is blank
        if row.organization and not row.org_employee_id:
            
            # Fetch the abbreviation (e.g., AQH-IND)
            company_abbr = frappe.db.get_value("Company", row.organization, "abbr")
            
            if company_abbr:
                prefix = company_abbr.strip().upper() + "-"
                
                # Check the database for existing Sub-IDs
                existing_subs = frappe.get_all(
                    "Employee Sub ID",
                    filters={"org_employee_id": ("like", f"{prefix}%")},
                    pluck="org_employee_id"
                )
                
                # Calculate the exact next number without relying on cache!
                if existing_subs:
                    numbers = []
                    for item in existing_subs:
                        if item:
                            try:
                                num = int(item.split("-")[-1])
                                numbers.append(num)
                            except:
                                pass
                    next_sub_num = max(numbers) + 1 if numbers else 1
                else:
                    next_sub_num = 1
                    
                # Stamp the perfect Sub-ID into the row!
                row.org_employee_id = f"{prefix}{str(next_sub_num).zfill(3)}"
